#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];
    /* The original binary used a 0x400‑byte buffer for the output.
       Allocate a bit more to be safe for the snake conversion which can
       increase the length (worst case: every character is an uppercase
       letter, doubling the size). */
    char out[2048];
    size_t out_idx = 0;

    if (strcmp(mode, "to_camel") == 0) {
        int capitalize = 0;
        for (size_t i = 0; input[i] && out_idx < sizeof(out) - 1; ++i) {
            char ch = input[i];
            if (ch == '_') {
                capitalize = 1;               // next letter becomes upper case
                continue;
            }
            if (capitalize && ch >= 'a' && ch <= 'z') {
                ch = (char)(ch - 'a' + 'A');   // make it upper case
            }
            out[out_idx++] = ch;
            capitalize = 0;
        }
        out[out_idx] = '\0';
        puts(out);
    } else if (strcmp(mode, "to_snake") == 0) {
        for (size_t i = 0; input[i] && out_idx < sizeof(out) - 1; ++i) {
            char ch = input[i];
            if (isupper((unsigned char)ch)) {
                if (out_idx != 0) {
                    out[out_idx++] = '_';
                }
                ch = (char)tolower((unsigned char)ch);
            }
            out[out_idx++] = ch;
        }
        out[out_idx] = '\0';
        puts(out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
